<?php
use Moves\Services\{Finance,OrganizationContext,OrganizationDirectory,OrganizationObligations,OrganizationTeam,SessionAuth};
$e=static fn(mixed$v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$org=OrganizationContext::current();if($org===null)return;$user=SessionAuth::current();$canManage=OrganizationTeam::can((int)$user['id'],(int)$org['id'],'finance.manage');$valid=static fn(mixed$v):bool=>is_string($v)&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$v);$start=$valid($_GET['inicio']??null)?$_GET['inicio']:date('Y-m-01');$end=$valid($_GET['fim']??null)?$_GET['fim']:date('Y-m-t',strtotime('+2 months'));$status=(string)($_GET['situacao']??'');$type=(string)($_GET['tipo']??'');$service=new OrganizationObligations((int)$org['id']);try{$data=$service->listing(['start'=>$start,'end'=>$end,'status'=>$status,'type'=>$type]);$members=OrganizationDirectory::members((int)$org['id']);}catch(Throwable$ex){error_log('Obligations page: '.$ex->getMessage());$data=['rows'=>[],'indicators'=>['pending'=>0,'upcoming'=>0,'overdue'=>0,'completed'=>0]];$members=[];}$flash=$_SESSION['obligations_flash']??null;unset($_SESSION['obligations_flash']);$labels=['pending'=>'Pendente','upcoming'=>'Próxima do vencimento','overdue'=>'Vencida','completed'=>'Concluída','cancelled'=>'Cancelada'];$types=['tax'=>'Fiscal','labor'=>'Trabalhista','license'=>'Licença','contract'=>'Contrato','other'=>'Outra'];
?>
<?php if(is_array($flash)):?><p class="finance-flash finance-flash-<?= $e($flash[0]) ?>"><?= $e($flash[1]) ?></p><?php endif;?>
<section class="card finance-workspace" aria-labelledby="obligations-title"><div class="finance-toolbar"><div><h2 id="obligations-title">Calendário de obrigações</h2><p class="muted">Agenda manual. O Realizze não calcula impostos nem gera despesas automaticamente.</p></div><?php if($canManage):?><button class="primary" type="button" data-finance-open="obligation-dialog">+ Nova obrigação</button><?php endif;?></div>
<div class="finance-goal-summary is-four"><?php foreach(['pending'=>'Pendentes','upcoming'=>'Próximas','overdue'=>'Vencidas','completed'=>'Concluídas']as$key=>$label):?><div class="finance-goal-stat finance-indicator <?= $key==='overdue'&&$data['indicators'][$key]>0?'is-overdue':'is-neutral' ?>"><span><?= $label ?></span><strong><?= (int)$data['indicators'][$key] ?></strong></div><?php endforeach;?></div>
<form class="finance-filter-bar" method="get" data-swap-get><label>De<input type="date" name="inicio" value="<?= $e($start) ?>"></label><label>Até<input type="date" name="fim" value="<?= $e($end) ?>"></label><label>Situação<select name="situacao"><option value="">Todas</option><?php foreach($labels as$key=>$label):?><option value="<?= $e($key) ?>"<?= $status===$key?' selected':'' ?>><?= $e($label) ?></option><?php endforeach;?></select></label><label>Tipo<select name="tipo"><option value="">Todos</option><?php foreach($types as$key=>$label):?><option value="<?= $e($key) ?>"<?= $type===$key?' selected':'' ?>><?= $e($label) ?></option><?php endforeach;?></select></label><button class="finance-button" type="submit">Filtrar</button></form>
<?php if($data['rows']===[]):?><div class="finance-empty"><h3>Nenhuma obrigação no período</h3><p>Cadastre compromissos reais da empresa; nenhuma obrigação fiscal é presumida.</p></div><?php else:?><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Obrigação</th><th>Competência</th><th>Vencimento</th><th>Responsável</th><th>Situação</th><th>Valor</th><th>Ações</th></tr></thead><tbody><?php foreach($data['rows']as$row):?><tr><td><strong><?= $e($row['title']) ?></strong><small><?= $e($types[$row['obligation_type']]??$row['obligation_type']) ?><?= (int)$row['sequence_no']>1?' · recorrência '.$e($row['sequence_no']):'' ?></small><?php foreach($row['attachments']as$file):?><a class="entry-chip is-file" href="/minha-conta/obrigacoes/comprovante/<?= (int)$file['id'] ?>" download><?= $e($file['original_name']) ?></a><?php endforeach;?></td><td><?= $e((new DateTimeImmutable($row['competence_date']))->format('m/Y')) ?></td><td><?= $e((new DateTimeImmutable($row['due_date']))->format('d/m/Y')) ?></td><td><?= $e($row['responsible_name']?:'Não definido') ?></td><td><span class="finance-badge <?= $row['display_status']==='overdue'?'is-overdue':($row['display_status']==='completed'?'is-paid':'is-open') ?>"><?= $e($labels[$row['display_status']]??$row['display_status']) ?></span></td><td><?= $row['amount_cents']!==null?$e(Finance::money((int)$row['amount_cents'])):'—' ?></td><td class="finance-actions"><?php if($canManage&&$row['status']==='pending'):?><form method="post" action="/minha-conta/obrigacoes/concluir"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button>Concluir</button></form><form method="post" action="/minha-conta/obrigacoes/cancelar" data-finance-confirm="Cancelar esta obrigação?"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="is-danger">Cancelar</button></form><?php elseif($canManage&&$row['status']==='completed'):?><form method="post" action="/minha-conta/obrigacoes/reabrir"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button>Reabrir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($canManage):?><dialog class="finance-dialog" id="obligation-dialog"><form method="post" action="/minha-conta/obrigacoes/salvar" enctype="multipart/form-data" data-finance-form><header><h2>Nova obrigação</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="idempotency_key" value="<?= $e(bin2hex(random_bytes(16))) ?>"><label>Nome<input name="title" maxlength="180" required></label><div class="finance-dialog-row"><label>Tipo<select name="type"><?php foreach($types as$key=>$label):?><option value="<?= $e($key) ?>"><?= $e($label) ?></option><?php endforeach;?></select></label><label>Periodicidade<select name="frequency"><option value="once">Única</option><option value="monthly">Mensal (12 ocorrências)</option><option value="quarterly">Trimestral (8 ocorrências)</option><option value="yearly">Anual (5 ocorrências)</option></select></label></div><div class="finance-dialog-row"><label>Competência<input type="date" name="competence_date" value="<?= $e(date('Y-m-01')) ?>" required></label><label>Vencimento<input type="date" name="due_date" value="<?= $e(date('Y-m-d')) ?>" required></label></div><div class="finance-dialog-row"><label>Responsável<select name="responsible_user_id"><option value="">Não definido</option><?php foreach($members as$member):if($member['status']==='active'):?><option value="<?= (int)$member['user_id'] ?>"><?= $e(trim($member['first_name'].' '.$member['last_name'])) ?></option><?php endif;endforeach;?></select></label><label>Valor opcional<input name="amount" inputmode="decimal" placeholder="0,00"></label></div><label>Descrição<textarea name="description" maxlength="5000"></textarea></label><label>Observações<textarea name="notes" maxlength="5000"></textarea></label><label>Comprovantes<input type="file" name="attachments[]" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.txt"><small>Até 5 arquivos, 10 MB cada.</small></label><footer><button type="button" data-finance-close>Cancelar</button><button class="primary">Salvar</button></footer></form></dialog><?php endif;?>
